import type { CharacterProfileDTO } from '../../services/api'
import { escapeHtml } from '../../utils/escapeHtml'
import { ImmersiveProfileFrame } from './ImmersiveProfileFrame'

type ProfileProps = { profile: CharacterProfileDTO }

function profileName(profile: CharacterProfileDTO, fallback: string) {
  return escapeHtml(profile.display_name || fallback)
}

function profileTags(profile: CharacterProfileDTO, className = 'tag') {
  return (profile.tags || [])
    .map((tag) => `<span class="${className}">${escapeHtml(tag)}</span>`)
    .join('')
}

function documentHtml(title: string, background: string, css: string, body: string) {
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style>
*{box-sizing:border-box;margin:0;padding:0;letter-spacing:0}html{background:${background}}body{min-width:0;background:${background};overflow-x:hidden}button,summary{font:inherit}summary{cursor:pointer} ${css}
</style></head><body>${body}</body></html>`
}

function renderProfileFrame(profile: CharacterProfileDTO, fallbackName: string, html: string, height = 1480) {
  return (
    <ImmersiveProfileFrame
      title={`${profile.display_name || fallbackName}角色档案`}
      html={html}
      fallbackHeight={height}
    />
  )
}

